import type { RunsIndex } from './types.js';

export { bandColor, findTrial, formatBytes, formatDuration, modelColor } from './format.js';

// The build-time snapshot. Used for instant first paint and as the
// fallback when the live /api/index endpoint isn't reachable (e.g.
// `vite preview` of a production build). Live data comes from useRuns().
//
// runs-index.json is generated by `pnpm scan` and not checked into git, so
// it's loaded via import.meta.glob — which tolerates zero matches — rather
// than a static import that would fail typecheck/build when it's absent.
const indexModules = import.meta.glob<{ default: RunsIndex }>('./data/runs-index.json', {
  eager: true,
});

const EMPTY_INDEX: RunsIndex = {
  generatedAt: '',
  runsRoot: '',
  counts: { trials: 0, running: 0, scored: 0, passed: 0 },
  scenarios: [],
  models: [],
  days: [],
  trials: [],
};

export const staticRuns: RunsIndex = indexModules['./data/runs-index.json']?.default ?? EMPTY_INDEX;
